#include <stdio.h>

#define MAXN 50005
#define MAXE 100005

int N;
int head[MAXN], to[MAXE], nxt[MAXE], ec = 0;
int dist[MAXN], parent[MAXN], q[MAXN], path[MAXN];
int st_u[MAXN], st_p[MAXN], st_d[MAXN];

void add_edge(int u, int v) {
    to[ec] = v;
    nxt[ec] = head[u];
    head[u] = ec++;
}

int farthest(int start) {
    for (int i = 1; i <= N; ++i) {
        dist[i] = -1;
        parent[i] = 0;
    }

    int front = 0, rear = 0;
    dist[start] = 0;
    q[rear++] = start;

    int far = start;

    while (front < rear) {
        int u = q[front++];

        if (dist[u] > dist[far]) far = u;

        for (int e = head[u]; e != -1; e = nxt[e]) {
            int v = to[e];
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                parent[v] = u;
                q[rear++] = v;
            }
        }
    }

    return far;
}

int count_at_depth(int start, int par, int d0, int target) {
    if (d0 > target) return 0;

    int top = 0;
    st_u[top] = start;
    st_p[top] = par;
    st_d[top] = d0;
    ++top;

    int cnt = 0;

    while (top > 0) {
        --top;

        int u = st_u[top];
        int p = st_p[top];
        int d = st_d[top];

        if (d == target) {
            ++cnt;
            continue;
        }

        for (int e = head[u]; e != -1; e = nxt[e]) {
            int v = to[e];
            if (v == p) continue;

            st_u[top] = v;
            st_p[top] = u;
            st_d[top] = d + 1;
            ++top;
        }
    }

    return cnt;
}

int main(void) {
    if (scanf("%d", &N) != 1) return 0;

    for (int i = 1; i <= N; ++i) head[i] = -1;

    for (int i = 0; i < N - 1; ++i) {
        int x, y;
        scanf("%d %d", &x, &y);
        add_edge(x, y);
        add_edge(y, x);
    }

    int A = farthest(1);
    int B = farthest(A);
    int D = dist[B];

    int cur = B;
    int idx = D;

    while (cur != A) {
        path[idx--] = cur;
        cur = parent[cur];
    }
    path[0] = A;

    long long ans;

    if (D % 2 == 0) {
        int R = D / 2;
        int c = path[R];

        long long S = 0, sq = 0;

        for (int e = head[c]; e != -1; e = nxt[e]) {
            int v = to[e];
            int cnt = count_at_depth(v, c, 1, R);
            S += cnt;
            sq += (long long)cnt * cnt;
        }

        ans = (S * S - sq) / 2;
    } else {
        int R = D / 2;
        int c1 = path[R];
        int c2 = path[R + 1];

        long long a = count_at_depth(c1, c2, 0, R);
        long long b = count_at_depth(c2, c1, 0, R);

        ans = a * b;
    }

    printf("%d\n%lld\n", D + 1, ans);

    return 0;
}
